ch := make(chan int) // 无缓冲 channel：没人接收时，发送方永久阻塞
go func() {
	ch <- 1 // 发送方卡在这里，就是最常见的 goroutine 泄露
}()

ctx, cancel := context.WithCancel(context.Background())
defer cancel() // 派生了就必须取消，否则等 ctx.Done() 的 goroutine 全部滞留
go func() {
	<-ctx.Done() // 永久等取消信号
}()

// 唯一的 goroutine 往一个没人收的 channel 发送：永久阻塞，运行时判定为死锁
ch := make(chan int)
ch <- 1

var counter int
var wg sync.WaitGroup
wg.Add(2)
for i := 0; i < 2; i++ {
	go func() {
		defer wg.Done()
		counter++ // 没有同步：这是 data race，go test -race 会报出来
	}()
}
wg.Wait()
fmt.Println(counter)

// 信号量：最多 10 个并发请求打同一个下游，满了就在发送处阻塞形成背压
sem := make(chan struct{}, 10)
sem <- struct{}{}
defer func() { <-sem }() // 用完立刻归还
